import java.util.Objects;
public class Fraction {private int num,den;public Fraction(int num,int den){if(den==0)throw new IllegalArgumentException("Denominator cannot be zero");int g=gcd(Math.abs(num),Math.abs(den));this.num=num/g;this.den=den/g;if(this.den<0){this.num=-this.num;this.den=-this.den;}}private int gcd(int a,int b){while(b!=0){int t=b;b=a%b;a=t;}return a==0?1:a;}public String toString(){return num+"/"+den;}public boolean equals(Object o){if(!(o instanceof Fraction))return false;Fraction f=(Fraction)o;return num==f.num&&den==f.den;}public int hashCode(){return Objects.hash(num,den);}}
